#!/usr/bin/env python3
"""PreToolUse guard: protects vendored assets, generated files, committed migrations and the dev database."""

from __future__ import annotations

import re
from fnmatch import fnmatch

from _common import ask, committed, deny, project_path, read_event, tool_input

# (path or directory prefix, why it must not be edited by hand)
GENERATED = [
    ("vendor/", "Composer-managed. Change composer.json and run `make composer ARGS=\"require|update ...\"`."),
    ("var/", "Symfony cache, logs and the SQLite test database."),
    ("public/assets/", "AssetMapper's compiled output; `make assets` rebuilds it."),
    ("public/bundles/", "Installed by assets:install."),
    ("assets/vendor/", "importmap dependencies, written by `importmap:install` / `importmap:require` (committed on purpose)."),
    ("assets/fullcalendar/", "FullCalendar's own global bundles and Classic theme, vendored as published. Re-skin the "
                             "calendar through the design tokens in assets/styles/app.css instead."),
    ("config/reference.php", "Regenerated by Symfony on every cache:clear (Rector skips it for the same reason)."),
    ("composer.lock", "Update it with `make composer ARGS=\"require|update <package>\"`."),
    ("symfony.lock", "Maintained by Symfony Flex when recipes run."),
]

# A compose project named "*-dep-check" is the dependency-upgrader agent's disposable copy.
DEP_CHECK = re.compile(r"(-p|--project-name)[ =]\S*dep-check\b")
NODE_TOOLING = re.compile(r"(^|[;&|(]\s*)(npm|npx|yarn|pnpm|bun|bunx)\b")
SCHEMA_UPDATE = re.compile(r"doctrine:schema:(update|drop)\b")
DELETES_VOLUMES = re.compile(r"\bdocker[- ]compose\b[^;&|]*\bdown\b[^;&|]*(\s-v\b|--volumes)|\bdocker\s+volume\s+(rm|prune)\b|\bmake\s+clean\b")
PURGES_DATA = re.compile(r"doctrine:fixtures:load\b|\bmake\s+fixtures\b")


def check_bash(command: str) -> None:
    if command.lstrip().startswith("git "):
        return  # commit messages and the like only mention these commands
    if NODE_TOOLING.search(command):
        deny(
            "This project has no Node.js toolchain by design. Front-end packages come from AssetMapper's importmap: "
            "`make console ARGS=\"importmap:require <package>\"` adds one under assets/vendor/ (committed), and "
            "`make assets` compiles. FullCalendar is a vendored global bundle in assets/fullcalendar/."
        )
    if SCHEMA_UPDATE.search(command):
        deny(
            "Schema changes go through migrations (`make console ARGS=\"make:migration\"`, review the PostgreSQL DDL, "
            "then `make migrate`). Production only ever runs migrations."
        )
    if DELETES_VOLUMES.search(command) and not DEP_CHECK.search(command):
        ask("Deletes the Postgres volume: every local account, customer and booking.")
    if PURGES_DATA.search(command):
        ask("Purges the development database and replaces it with the demo fixtures.")


def check_edit(rel: str) -> None:
    for prefix, reason in GENERATED:
        if rel == prefix or (prefix.endswith("/") and rel.startswith(prefix)):
            deny(f"{rel} is not hand-edited: {reason}")
    if fnmatch(rel, "migrations/Version*.php") and committed(rel):
        deny(
            f"{rel} is a committed migration; the entrypoint has already applied it on Render/Neon. "
            "Generate a new one with `make console ARGS=\"make:migration\"`."
        )


def main() -> None:
    event = read_event()
    if event.get("tool_name") == "Bash":
        check_bash(tool_input(event).get("command", ""))
        return
    rel = project_path(event)
    if rel is not None:
        check_edit(rel)


if __name__ == "__main__":
    main()
